document.addEventListener("DOMContentLoaded",()=>{const t=document.getElementById("retryBtn"),e=document.getElementById("retryNote"),n=document.getElementById("retryCountdown");if(!t||!n)return;let d=30;const r=setInterval(()=>{var o;d--,d<=0?(clearInterval(r),t.disabled=!1,e.innerHTML='<i class="fa-solid fa-circle-check"></i> يمكنك الآن إعادة المحاولة'):n.textContent=(o=d,`${Math.floor(o/60).toString().padStart(2,"0")}:${(o%60).toString().padStart(2,"0")}`)},1e3);t.addEventListener("click",()=>{t.disabled||location.reload()})});